package aaa;

// A lookupswitch with no cases, only a default (scalac emits these for some
// pattern matches), assembled by hand (generated by a small script;
// version 49):
//
//   static int f(int x) { iload_0; lookupswitch { default: 12 }; 12: iload_0; iconst_1; iadd; ireturn }
//
// OpenLDK started no block at the lone target, and jumped to a label it
// never emitted.
public class emptyswitch extends ClassLoader
{
    private static final byte[] SW = new byte[] {
        -54,-2,-70,-66,0,0,0,49,0,8,1,0,18,97,97,97,47,101,109,112,116,121,115,119,105,116,99,104,36,83,119,7,0,1,1,0,16,106,97,118,97,47,108,97,110,103,47,79,98,106,101,99,116,7,0,3,1,0,4,67,111,100,101,1,0,1,102,1,0,4,40,73,41,73,0,33,0,2,0,4,0,0,0,0,0,1,0,9,0,6,0,7,0,1,0,5,0,0,0,28,0,2,0,1,0,0,0,16,26,-85,0,0,0,0,0,11,0,0,0,0,26,4,96,-84,0,0,0,0,0,0
    };

    protected Class<?> findClass(String name) throws ClassNotFoundException
    {
        if (!name.equals("aaa.emptyswitch$Sw")) throw new ClassNotFoundException(name);
        return defineClass(name, SW, 0, SW.length);
    }

    public static void main(String[] args) throws Exception
    {
        Class<?> c = new emptyswitch().loadClass("aaa.emptyswitch$Sw");
        Object result;
        try { result = c.getMethod("f", int.class).invoke(null, 41); }
        catch (Throwable t) { result = "escaped: " + t; }
        System.out.println(Integer.valueOf(42).equals(result) ? "OK" : "FAIL: " + result);
    }
}
